from decimal import Decimal, InvalidOperation
import re

parts = [p.strip().lstrip("$") for p in re.split(r"[,\n]+", raw) if p.strip()]
if not parts:
    raise ValueError("no amounts were entered")

values = []
for p in parts:
    try:
        v = Decimal(p)
    except InvalidOperation:
        raise ValueError(f"'{p}' is not an amount")
    if v < 0:
        raise ValueError(f"'{p}' is negative; expenses must be zero or more")
    values.append(v)

total = sum(values, Decimal("0")).quantize(Decimal("0.01"))
return {"amounts": [float(v) for v in values], "total": float(total)}
